/**
 * Line Ingredient Mapper
 * Maps SCADA line product names (from ML#.CURRENTSILOPRODUCTNAME) to NetSuite
 * raw ingredient items. These names are system-generated by SCADA/Atlas, not
 * operator free-text, so a direct lookup table works.
 *
 * Used by blendTankMesService.processLineFlow() to match line flow totals
 * against WO BOM components for automatic ingredient issuing.
 */

const itemConfig = require('./mesItemConfig')

// SCADA product name → NS raw ingredient item
// Keys are normalized (lowercase, trimmed). Values reference mesItemConfig items.
const LINE_PRODUCT_MAP = {
  // ── Conventional ──

  // 0% / Fat Free / Skim (0% = skim = fat free — all the same item)
  'raw conventional 0%':         { id: 5477, name: 'Raw Conventional 0%' },
  'conventional fat free':       { id: 5477, name: 'Raw Conventional 0%' },
  'conventional 0%':             { id: 5477, name: 'Raw Conventional 0%' },
  'conv fat free':               { id: 5477, name: 'Raw Conventional 0%' },
  'conventional skim':           { id: 5477, name: 'Raw Conventional 0%' },
  'raw conventional skim':       { id: 5477, name: 'Raw Conventional 0%' },

  // Standardized fat percentages
  'raw conventional 1%':         { id: 5415, name: 'Raw Conventional 1%' },
  'conventional 1%':             { id: 5415, name: 'Raw Conventional 1%' },
  'conventional low fat 1%':     { id: 5415, name: 'Raw Conventional 1%' },
  'raw conventional 2%':         { id: 5412, name: 'Raw Conventional 2%' },
  'conventional 2%':             { id: 5412, name: 'Raw Conventional 2%' },
  'conventional low fat 2%':     { id: 5412, name: 'Raw Conventional 2%' },
  'raw conventional 3.25%':      { id: 5413, name: 'Raw Conventional 3.25%' },
  'conventional 3.25%':          { id: 5413, name: 'Raw Conventional 3.25%' },
  'raw conventional 3.5%':       { id: 5416, name: 'Raw Conventional 3.5%' },
  'conventional 3.5%':           { id: 5416, name: 'Raw Conventional 3.5%' },

  // Whole milk
  'raw conventional':            { id: 5417, name: 'Raw Conventional Milk' },
  'raw conventional milk':       { id: 5417, name: 'Raw Conventional Milk' },

  // Cream
  'raw conventional cream':      { id: 5480, name: 'Raw Conventional Cream' },
  'conventional cream':          { id: 5480, name: 'Raw Conventional Cream' },

  // UF Milk
  'raw conventional uf milk':    { id: 5405, name: 'Raw Conventional UF Milk' },
  'conventional uf milk':        { id: 5405, name: 'Raw Conventional UF Milk' },
  'conventional uf':             { id: 5405, name: 'Raw Conventional UF Milk' },

  // ── Organic ──

  // 0% / Fat Free / Skim (0% = skim = fat free — all the same item)
  'raw organic 0%':              { id: 5482, name: 'Raw Organic 0%' },
  'organic fat free':            { id: 5482, name: 'Raw Organic 0%' },
  'organic 0%':                  { id: 5482, name: 'Raw Organic 0%' },
  'organic skim':                { id: 5482, name: 'Raw Organic 0%' },
  'raw organic skim':            { id: 5482, name: 'Raw Organic 0%' },

  // Standardized fat percentages
  'raw organic 1%':              { id: 5409, name: 'Raw Organic 1%' },
  'organic 1%':                  { id: 5409, name: 'Raw Organic 1%' },
  'raw organic 2%':              { id: 5410, name: 'Raw Organic 2%' },
  'organic 2%':                  { id: 5410, name: 'Raw Organic 2%' },
  'raw organic 3.25%':           { id: 5411, name: 'Raw Organic 3.25%' },
  'organic 3.25%':               { id: 5411, name: 'Raw Organic 3.25%' },
  'raw organic 3.5%':            { id: 5481, name: 'Raw Organic 3.5%' },
  'organic 3.5%':                { id: 5481, name: 'Raw Organic 3.5%' },

  // Whole milk
  'raw organic':                 { id: 5404, name: 'Raw Organic Milk' },
  'raw organic milk':            { id: 5404, name: 'Raw Organic Milk' },

  // Cream
  'raw organic cream':           { id: 5483, name: 'Raw Organic Cream' },
  'organic cream':               { id: 5483, name: 'Raw Organic Cream' },

  // UF Milk
  'raw organic uf milk':         { id: 5402, name: 'Raw Organic UF Milk' },
  'organic uf milk':             { id: 5402, name: 'Raw Organic UF Milk' },
  'organic uf':                  { id: 5402, name: 'Raw Organic UF Milk' },

  // A2 variants
  'raw organic a2 milk':         { id: 5403, name: 'Raw Organic A2 Milk' },
  'organic a2 milk':             { id: 5403, name: 'Raw Organic A2 Milk' },
  'raw organic a2 0%':           { id: 5482, name: 'Raw Organic 0%' },          // no separate A2 0% item — use organic 0%
  'raw organic grade a (a2/a2) milk': { id: 5406, name: 'Raw Organic Grade A (A2/A2) Milk' },
}

/**
 * Resolve a SCADA line product name to a NS raw ingredient item.
 * @param {string} productName - from ML#.CURRENTSILOPRODUCTNAME tag
 * @returns {{ id: number, name: string } | null}
 */
function resolveLineProduct(productName) {
  if (!productName || typeof productName !== 'string') return null

  const normalized = productName.toLowerCase().trim()

  // Direct lookup
  if (LINE_PRODUCT_MAP[normalized]) {
    return LINE_PRODUCT_MAP[normalized]
  }

  // Partial match — check if any key is contained in the input or vice versa
  for (const [key, item] of Object.entries(LINE_PRODUCT_MAP)) {
    if (normalized.includes(key) || key.includes(normalized)) {
      return item
    }
  }

  console.warn(`[LineIngredientMapper] No match for SCADA product name: "${productName}"`)
  return null
}

/**
 * Given a resolved NS item and a list of BOM component items from the WO,
 * find the matching BOM component row.
 * @param {{ id: number }} resolvedItem - from resolveLineProduct()
 * @param {Array} bomItems - from NS workOrder expandSubResources (item.items)
 * @returns {object|null} - the matching BOM component row
 */
function matchBomComponent(resolvedItem, bomItems) {
  if (!resolvedItem?.id || !bomItems?.length) return null

  const itemId = String(resolvedItem.id)
  return bomItems.find(c => {
    const compId = String(c.item?.id || c.item)
    return compId === itemId
  }) || null
}

module.exports = {
  resolveLineProduct,
  matchBomComponent,
  LINE_PRODUCT_MAP,
}
